// Des: Privacy: owner-only data folder, purge old logs, redact private text
// Flo: lock folder to the owner (chmod 700 or icacls) > purge log rows older than msgs_keep_days > redact emails, phones, long numbers, names after by/from
// I/O: folder path + user name (caller) > best-effort permission change; redacted text (arena owned)
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const task = @import("ru-task-runn.zig");
const CF = .{ .dayz = 86400000, .tmo = 15000, .numz = 6 };
fn runOk(gpaz: std.mem.Allocator, iozz: std.Io, argv: []const []const u8) ?[]u8 { const res = std.process.run(gpaz, iozz, .{ .argv = argv, .stdout_limit = .limited(4096), .stderr_limit = .limited(4096), .timeout = .{ .duration = .{ .raw = .fromMilliseconds(CF.tmo), .clock = .awake } } }) catch return null; defer gpaz.free(res.stderr); const good = switch (res.term) { .exited => |cod| cod == 0, else => false }; if (!good) { gpaz.free(res.stdout); return null; } return res.stdout; }
fn sidGrant(gpaz: std.mem.Allocator, iozz: std.Io, buf: []u8) ?[]const u8 { const out = runOk(gpaz, iozz, &.{ "C:\\Windows\\System32\\whoami.exe", "/user", "/fo", "csv", "/nh" }) orelse runOk(gpaz, iozz, &.{ "whoami.exe", "/user", "/fo", "csv", "/nh" }) orelse return null; defer gpaz.free(out); const at = std.mem.lastIndexOf(u8, out, ",\"") orelse return null; const end = std.mem.findScalarPos(u8, out, at + 2, '"') orelse return null; const sid = out[at + 2 .. end]; if (sid.len < 4 or sid[0] != 'S') return null; return std.fmt.bufPrint(buf, "*{s}:(OI)(CI)F", .{sid}) catch null; }
pub fn lockDown(gpaz: std.mem.Allocator, iozz: std.Io, dir: []const u8, grant: []const u8) bool { if (builtin.os.tag != .windows) { const out = runOk(gpaz, iozz, &.{ "chmod", "700", dir }) orelse return false; gpaz.free(out); return true; } var buf: [128]u8 = undefined; _ = grant; const who = sidGrant(gpaz, iozz, &buf) orelse return false; const g1 = runOk(gpaz, iozz, &.{ "icacls", dir, "/grant:r", who }) orelse return false; gpaz.free(g1); const g2 = runOk(gpaz, iozz, &.{ "icacls", dir, "/inheritance:r" }) orelse return false; gpaz.free(g2); return true; }
pub fn grantFor(aren: std.mem.Allocator, user: []const u8) ![]u8 { return std.fmt.allocPrint(aren, "{s}:(OI)(CI)F", .{user}); }
pub fn purge(ctx: *task.Ctx) !i64 { const cut = task.nowMs(ctx) - @as(i64, ctx.conf.msgs_keep_days) * CF.dayz; const lg = try ctx.store.logPurge(cut); const ac = try ctx.store.actPurge(cut); return lg + ac; }
fn digitsIn(tok: []const u8) usize { var cnt: usize = 0; for (tok) |chr| { if (chr >= '0' and chr <= '9') cnt += 1; } return cnt; }
fn lowEq(tok: []const u8, want: []const u8) bool { return std.ascii.eqlIgnoreCase(std.mem.trim(u8, tok, ".,:;()\"'"), want); }
fn isNumTok(tok: []const u8) bool { if (tok.len == 0) return false; var dig = false; for (tok) |chr| { if (chr >= '0' and chr <= '9') { dig = true; } else if (chr != '+' and chr != '-' and chr != '.' and chr != '(' and chr != ')') return false; } return dig; }
fn isSep(chr: u8) bool { return chr == ' ' or chr == '\n' or chr == '\t' or chr == '\r'; }
pub fn redact(aren: std.mem.Allocator, text: []const u8) ![]u8 { var out: std.ArrayList(u8) = .empty; var names: u32 = 0; var idx: usize = 0; while (idx < text.len) { if (isSep(text[idx])) { try out.append(aren, text[idx]); idx += 1; continue; } var end = idx; while (end < text.len and !isSep(text[end])) end += 1; const tok = text[idx..end]; if (isNumTok(tok)) { var sum = digitsIn(tok); var e2 = end; while (e2 < text.len and text[e2] == ' ') { var s2 = e2; while (s2 < text.len and text[s2] == ' ') s2 += 1; var t2 = s2; while (t2 < text.len and !isSep(text[t2])) t2 += 1; if (t2 == s2 or !isNumTok(text[s2..t2])) break; sum += digitsIn(text[s2..t2]); e2 = t2; } if (sum >= CF.numz and e2 > end) { try out.appendSlice(aren, "[num]"); idx = e2; continue; } } if (std.mem.findScalar(u8, tok, '@') != null and std.mem.findScalar(u8, tok, '.') != null) { try out.appendSlice(aren, "[email]"); } else if (digitsIn(tok) >= CF.numz) { try out.appendSlice(aren, "[num]"); } else if (names > 0) { try out.appendSlice(aren, "[name]"); names -= 1; } else { try out.appendSlice(aren, tok); if (lowEq(tok, "by") or lowEq(tok, "from") or lowEq(tok, "bởi") or lowEq(tok, "từ")) names = 2; } idx = end; } return out.items; }
